dsl:
IMAGE down_jacket "羽绒服" x=300 y=170 w=200 h=240 z=5 vis=true animation={"entry":{"animId":"向下滑入"}}
WAIT 800
TEXT reveal_hint "这件是羽绒服。" x=270 y=430 z=10 block=true dismiss=true

TEXT focus_1 "位置一" x=160 y=280
TEXT focus_2 "位置二" x=360 y=280
TEXT focus_3 "位置三" x=560 y=280
STYLE focus_1 {"alpha":1,"scale":1.15}
STYLE focus_2 {"alpha":0.45,"scale":1}
STYLE focus_3 {"alpha":0.45,"scale":1}
WAIT 500
STYLE focus_1 {"alpha":0.45,"scale":1}
STYLE focus_2 {"alpha":1,"scale":1.15}
WAIT 500
STYLE focus_2 {"alpha":0.45,"scale":1}
STYLE focus_3 {"alpha":1,"scale":1.15}

VAR focusIdx = 0
IMAGE patient_01 "病人01" x=120 y=200 w=120 h=160 z=3 vis=true
IMAGE patient_02 "病人02" x=340 y=200 w=120 h=160 z=3 vis=true
IMAGE patient_03 "病人03" x=560 y=200 w=120 h=160 z=3 vis=true
LOOP focusIdx < 3
    STYLE patient_01 {"alpha":1,"zIndex":10}
    ANIM_IN patient_01 bounce ms=280
    WAIT 500
    STYLE patient_01 {"alpha":0.45,"zIndex":2}
    STYLE patient_02 {"alpha":1,"zIndex":10}
    ANIM_IN patient_02 bounce ms=280
    WAIT 500
    STYLE patient_02 {"alpha":0.45,"zIndex":2}
    STYLE patient_03 {"alpha":1,"zIndex":10}
    ANIM_IN patient_03 bounce ms=280
    WAIT 500
    STYLE patient_03 {"alpha":0.45,"zIndex":2}
    VAR focusIdx + 1

IMAGE reveal_capsule "黄色胶囊" x=40 y=280 w=120 h=80 z=20 vis=true
STYLE reveal_capsule {"alpha":0.45}
MOVE reveal_capsule 340 260 ms=900 keep=true
WAIT 200
STYLE reveal_capsule {"alpha":1,"zIndex":25}
ANIM_IN reveal_capsule scaleIn ms=450

IMAGE medicine_cabinet "药柜" x=430 y=170 w=180 h=220 z=2 vis=true
